/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: CreditRole, Subject, ReplayCatalog, BylineScenario, EmptyBylineScenario
 *   Functions: bylineVerdict, artist, organization, longName, syntheticCatalogDatabase, withSyntheticCatalog,
 *              replayBylineBuilders
 *   Constants: accepted, rejected, onlyAndroidAccepts, onlyIosAccepts, albumId, mediaTrackId, choir, trio,
 *              quartet, brass, strings, studio, choirNamesake, padded, celeste, gamma, longAlpha, longBeta,
 *              longGamma, zwjName, records, publishing, distribution, longLabel, longPublisher, voices,
 *              representativeScenarios, joinPhraseScenarios, emptyBylineScenarios
 *   Variables: seededRows
 * Tests
 *   - ported validators accept exactly the limit and reject one more
 *   - combining marks and emoji modifiers count once on iOS but per code point on Android
 *   - emoji ZWJ and tag sequences contain format characters that only iOS rejects
 *   - C0 and C1 controls are rejected by both clients wherever they appear
 *   - empty, whitespace-only and padded text is rejected while inner spaces are kept
 *   - an unpaired surrogate never decodes on iOS but counts as one code point on Android
 *   - every current server byline builder yields the same byline, accepted by both native clients
 *   - join-phrase bylines are identical on every builder and accepted by both native clients
 *   - an empty byline is omitted, so both native clients decode the summary and fall back to artistNames
 *   - known gaps: current bylines that a native client rejects
 * @end-catalog */

/**
 * Baseline for native byline compatibility. The first tests pin the ported iOS and Android
 * display-text validators (test/support/nativeDisplayTextValidators.ts) on Unicode edge cases.
 * The replay tests run every server builder that composes `displayByline` and require
 * identical bylines that both clients accept, so a byline change (join phrases, multi-artist
 * Credits, truncation) cannot silently make a Listener page or Album-details response
 * undecodable on one platform. Short expected bylines are literals captured from the pre-change
 * builders; long ones are pinned by code-point count. The shared composer changed only the
 * overflow case, now cut after the last whole name that fits plus an ellipsis, and came with
 * join-phrase replays. An owner with no visible credited subject must omit the byline, which
 * both clients replace with `artistNames`; an empty byline fails the iOS collection-page decoder
 * and Android's page and Album-details validation.
 * Every invisible or combining character is written as an escape so editors cannot alter it.
 */
import assert from 'node:assert/strict';
import test, { type TestContext } from 'node:test';
import { MongoClient, ObjectId, type Db, type Document } from 'mongodb';

import { connectToDatabase, disconnectFromDatabase } from '../../src/infrastructure/database';
import { databaseIndexes } from '../../src/infrastructure/databaseIndexes';
import {
    getListenerAlbum,
    getListenerAudioTrack
} from '../../src/services/listener/listenerContentService';
import {
    projectPublicAlbums,
    projectPublicAudioTracks,
    resolvePublicCatalogBylines
} from '../../src/services/catalog/publicCatalogService';
import {
    nativeAttributionOutcome,
    nativeBylineLimit,
    nativeCreditNameLimit,
    nativeDisplayTextVerdict
} from '../support/nativeDisplayTextValidators';

const accepted = { ios: true, android: true };
const rejected = { ios: false, android: false };
const onlyAndroidAccepts = { ios: false, android: true };
const onlyIosAccepts = { ios: true, android: false };
const bylineVerdict = (value: string) => nativeDisplayTextVerdict(value, nativeBylineLimit);

test('ported validators accept exactly the limit and reject one more', () => {
    assert.deepEqual(bylineVerdict('a'.repeat(500)), accepted);
    assert.deepEqual(bylineVerdict('a'.repeat(501)), rejected);
    // U+1F3BB is two UTF-16 units but one code point and one Character on both clients.
    assert.deepEqual(bylineVerdict('\u{1F3BB}'.repeat(500)), accepted);
    assert.deepEqual(bylineVerdict('\u{1F3BB}'.repeat(501)), rejected);
    assert.deepEqual(nativeDisplayTextVerdict('a'.repeat(200), nativeCreditNameLimit), accepted);
    assert.deepEqual(nativeDisplayTextVerdict('a'.repeat(201), nativeCreditNameLimit), rejected);
});

test('combining marks and emoji modifiers count once on iOS but per code point on Android', () => {
    const decomposed = 'e\u0301';
    assert.deepEqual(bylineVerdict(decomposed.repeat(250)), accepted);
    assert.deepEqual(bylineVerdict(decomposed.repeat(251)), onlyIosAccepts);
    assert.deepEqual(bylineVerdict(decomposed.repeat(500)), onlyIosAccepts);
    assert.deepEqual(bylineVerdict(decomposed.repeat(501)), rejected);
    assert.deepEqual(bylineVerdict(`a${'\u0301'.repeat(499)}`), accepted);
    assert.deepEqual(bylineVerdict(`a${'\u0301'.repeat(500)}`), onlyIosAccepts);
    for (const cluster of ['\u{1F44D}\u{1F3FD}', '\u{1F1EF}\u{1F1F5}']) {
        assert.deepEqual(bylineVerdict(cluster.repeat(250)), accepted, cluster);
        assert.deepEqual(bylineVerdict(cluster.repeat(251)), onlyIosAccepts, cluster);
    }
});

test('emoji ZWJ and tag sequences contain format characters that only iOS rejects', () => {
    const formatCharacterValues = [
        '\u{1F469}\u200D\u{1F4BB}',
        'Trio \u{1F468}\u200D\u{1F469}\u200D\u{1F467}',
        '\u{1F3F4}\u{E0067}\u{E0062}\u{E0065}\u{E006E}\u{E0067}\u{E007F}',
        'Ab\u00ADcd',
        'Ab\u200Bcd',
        'Ab\u200Ecd',
        'Ab\u2060cd',
        'Ab\uFEFFcd'
    ];
    for (const value of formatCharacterValues) {
        assert.deepEqual(bylineVerdict(value), onlyAndroidAccepts, JSON.stringify(value));
    }
    // A variation selector is a nonspacing mark (Mn), not a format character.
    assert.deepEqual(bylineVerdict('Heart \u2764\uFE0F'), accepted);
});

test('C0 and C1 controls are rejected by both clients wherever they appear', () => {
    const controls = ['\u0000', '\u0009', '\u000A', '\u000D', '\u001B', '\u001F', '\u007F', '\u0080', '\u0085', '\u009F'];
    for (const control of controls) {
        for (const value of [`Ab${control}cd`, `${control}Abcd`, `Abcd${control}`]) {
            assert.deepEqual(bylineVerdict(value), rejected, JSON.stringify(value));
        }
    }
});

test('empty, whitespace-only and padded text is rejected while inner spaces are kept', () => {
    // U+00A0 no-break space, U+3000 ideographic space, U+2028 line separator, U+2003 em space.
    const whitespaceOrPadded = ['', ' ', '   ', '\u00A0', '\u3000', '\u2028', ' Ab', 'Ab ', 'Ab\u00A0', '\u2003Ab'];
    for (const value of whitespaceOrPadded) {
        assert.deepEqual(bylineVerdict(value), rejected, JSON.stringify(value));
    }
    for (const value of ['Ab cd', 'Ab\u00A0cd', 'Ab\u3000cd']) {
        assert.deepEqual(bylineVerdict(value), accepted, JSON.stringify(value));
    }
    // Titles opt into empty text; bylines and Credit names never do.
    assert.deepEqual(nativeDisplayTextVerdict('', nativeBylineLimit, true), accepted);
});

test('an unpaired surrogate never decodes on iOS but counts as one code point on Android', () => {
    assert.deepEqual(bylineVerdict('Ab\uD800cd'), onlyAndroidAccepts);
    assert.deepEqual(bylineVerdict('\uDC00'), onlyAndroidAccepts);
});

type CreditRole = 'primary' | 'featured' | 'performer' | 'composer' | 'producer' | 'remixer'
    | 'label' | 'publisher' | 'distributor';
interface Subject { subjectType: 'artist' | 'organization'; subjectId: string; name: string }
/** Stored attribution of the replayed Album and MediaTrack. */
interface ReplayCatalog {
    /** Subject, role and an optional stored join phrase (which may be invalid). */
    credits: Array<[Subject, CreditRole, string?]>;
    attributionStatus?: 'documented' | 'unknown';
    /** Credited subjects the ready/public filters exclude, so they are never seeded. */
    hiddenSubjects?: Subject[];
    /** Legacy MediaTrack Artist IDs, the `artistNames` source when no credited Artist is visible. */
    trackArtists?: Subject[];
}
interface BylineScenario extends ReplayCatalog {
    title: string;
    byline: string;
    codePoints?: number;
}
/** An owner whose byline is empty, with the byline each client then shows. */
interface EmptyBylineScenario extends ReplayCatalog {
    title: string;
    albumFallback: string | null;
    trackFallback: string | null;
    /** Stored attribution is unusable, so every DTO omits all three attribution fields. */
    noAttribution?: true;
}

const albumId = '64b0000000000000000000b1';
const mediaTrackId = '64b0000000000000000000d1';
const artist = (index: number, name: string): Subject =>
    ({ subjectType: 'artist', subjectId: `64b00000000000000000${(0xa000 + index).toString(16)}`, name });
const organization = (index: number, name: string): Subject =>
    ({ subjectType: 'organization', subjectId: `64b00000000000000000${(0xc000 + index).toString(16)}`, name });
/** A synthetic name at the 200-character limit both clients enforce for Credit names. */
const longName = (label: string) => `${label} ${'x'.repeat(199 - label.length)}`;

const choir = artist(1, 'Northwind Choir');
const trio = artist(2, 'Ipsum Trio');
const quartet = artist(3, 'Dolor Quartet');
const brass = artist(4, 'Sitamet Brass');
const strings = artist(5, 'Consectetur Strings');
const studio = artist(6, 'Adipiscing Studio');
const choirNamesake = artist(7, 'Northwind Choir');
const padded = artist(8, '  Padded Ensemble  ');
// U+0301 combining acute accent after a plain "e", so the name stays decomposed.
const celeste = artist(9, 'Ensemble Ce\u0301leste \u{1F3BB}');
const gamma = artist(10, 'Gamma \u{1F44D}\u{1F3FD} Duo \u{1F1EF}\u{1F1F5}');
const longAlpha = artist(11, longName('Long Alpha'));
const longBeta = artist(12, longName('Long Beta'));
const longGamma = artist(13, longName('Long Gamma'));
const zwjName = artist(14, 'Pixel \u{1F469}\u200D\u{1F4BB} Collective');
const records = organization(1, 'Lorem Records');
const publishing = organization(2, 'Elit Publishing');
const distribution = organization(3, 'Tempor Distribution');
const longLabel = organization(4, longName('Long Label'));
const longPublisher = organization(5, longName('Long Publisher'));
const voices = Array.from({ length: 50 }, (_, index) =>
    artist(100 + index, `Voice ${String(index + 1).padStart(2, '0')}`));

const representativeScenarios: BylineScenario[] = [
    { title: 'one primary Artist', credits: [[choir, 'primary']], byline: 'Northwind Choir' },
    {
        title: 'several primary Artists with featured and performer Credits in Credit order',
        credits: [
            [choir, 'primary'], [trio, 'primary'], [brass, 'featured'], [quartet, 'primary'],
            [strings, 'performer'], [studio, 'composer'], [records, 'label']
        ],
        byline: 'Northwind Choir, Ipsum Trio, Sitamet Brass, Dolor Quartet, Consectetur Strings'
    },
    {
        title: 'Organizations only',
        credits: [[records, 'label'], [publishing, 'publisher'], [distribution, 'distributor']],
        byline: 'Lorem Records, Elit Publishing, Tempor Distribution'
    },
    {
        title: 'an Organization replaces non-performing Artist roles',
        credits: [[studio, 'composer'], [trio, 'producer'], [records, 'label']],
        byline: 'Lorem Records'
    },
    {
        title: 'non-performing Artist roles alone fall back to every Credit',
        credits: [[studio, 'composer'], [trio, 'producer'], [quartet, 'remixer']],
        byline: 'Adipiscing Studio, Ipsum Trio, Dolor Quartet'
    },
    {
        title: 'a repeated name appears once at its first position',
        credits: [[choir, 'primary'], [choir, 'performer'], [choirNamesake, 'primary'], [trio, 'primary']],
        byline: 'Northwind Choir, Ipsum Trio'
    },
    {
        title: 'stored names are trimmed',
        credits: [[padded, 'primary'], [trio, 'featured']],
        byline: 'Padded Ensemble, Ipsum Trio'
    },
    { title: 'unknown attribution', credits: [], attributionStatus: 'unknown', byline: 'Attribution not documented' },
    {
        title: 'combining marks, emoji modifiers and flags',
        credits: [[celeste, 'primary'], [gamma, 'primary']],
        byline: 'Ensemble Ce\u0301leste \u{1F3BB}, Gamma \u{1F44D}\u{1F3FD} Duo \u{1F1EF}\u{1F1F5}'
    },
    { title: 'one 200-character name', credits: [[longAlpha, 'primary']], byline: longAlpha.name, codePoints: 200 },
    {
        title: 'two 200-character primary names with a label',
        credits: [[longAlpha, 'primary'], [longBeta, 'primary'], [records, 'label']],
        byline: `${longAlpha.name}, ${longBeta.name}`,
        codePoints: 402
    },
    {
        title: 'two 200-character Organization names',
        credits: [[longLabel, 'label'], [longPublisher, 'publisher']],
        byline: `${longLabel.name}, ${longPublisher.name}`,
        codePoints: 402
    },
    {
        title: 'fifty short primary names at the Credit maximum',
        credits: voices.map((voice): [Subject, CreditRole] => [voice, 'primary']),
        byline: voices.map((voice) => voice.name).join(', '),
        codePoints: 498
    },
    {
        // Joined, the names take 604 code points, so the byline keeps the last whole name that
        // fits followed by U+2026. Android (CatalogRepository.kt:696) counts code points.
        title: 'three 200-character primary names end after the last whole name',
        credits: [[longAlpha, 'primary'], [longBeta, 'primary'], [longGamma, 'primary']],
        byline: `${longAlpha.name}, ${longBeta.name}\u2026`,
        codePoints: 403
    }
];

/** Bylines with stored join phrases; an invalid phrase (U+200B) is presented as `, `. */
const joinPhraseScenarios: BylineScenario[] = [
    {
        title: 'ampersand without spaces',
        credits: [[choir, 'primary', '&'], [trio, 'primary']],
        byline: 'Northwind Choir&Ipsum Trio'
    },
    {
        title: 'ideographic comma',
        credits: [[choir, 'primary', '\u3001'], [trio, 'primary']],
        byline: 'Northwind Choir\u3001Ipsum Trio'
    },
    {
        title: 'featured phrase before a featured Credit, label omitted',
        credits: [[choir, 'primary', ' & '], [trio, 'primary', ' feat. '], [brass, 'featured'], [records, 'label']],
        byline: 'Northwind Choir & Ipsum Trio feat. Sitamet Brass'
    },
    {
        title: 'an invalid stored phrase falls back to a comma',
        credits: [[choir, 'primary', 'x\u200By'], [trio, 'primary']],
        byline: 'Northwind Choir, Ipsum Trio'
    }
];

/**
 * Owners whose byline is empty because no credited subject is visible, or stored attribution is
 * unusable. The server omits `displayByline` (native collection-page decoders reject ''), so
 * clients fall back to `artistNames`. The Album's list holds only visible primary and featured
 * Artist Credits; the MediaTrack's falls back to its legacy Artist IDs.
 */
const emptyBylineScenarios: EmptyBylineScenario[] = [
    {
        title: 'every credited Artist and Organization is hidden',
        credits: [[choir, 'primary'], [brass, 'featured'], [records, 'label']],
        hiddenSubjects: [choir, brass, records],
        trackArtists: [trio],
        albumFallback: null,
        trackFallback: 'Ipsum Trio'
    },
    {
        // Documented attribution needs a Credit, so the stored list fails validation and the
        // owner carries no attribution field at all.
        title: 'documented attribution with no stored Credit',
        credits: [],
        trackArtists: [trio, quartet],
        albumFallback: null,
        trackFallback: 'Ipsum Trio, Dolor Quartet',
        noAttribution: true
    }
];

/** Rows the synthetic database returns for each collection; replaced before every replay. */
let seededRows: Record<string, Document[]> = {};

/**
 * A read-only stand-in that returns each seeded collection whole. Filters are not evaluated, so
 * scenarios seed only ready, public subjects; the services' own lifecycle, visibility and Credit
 * checks still shape the output. Rows are shallow-cloned so ObjectId values keep their prototype.
 */
const syntheticCatalogDatabase = () => {
    const cursor = (collection: string) => {
        const documents = () => (seededRows[collection] ?? []).map((document) => ({ ...document }));
        const chain = {
            project: () => chain,
            sort: () => chain,
            skip: () => chain,
            limit: () => chain,
            maxTimeMS: () => chain,
            toArray: async () => documents(),
            next: async () => documents()[0] ?? null
        };
        return chain;
    };
    return {
        command: async () => ({
            isWritablePrimary: true,
            setName: 'synthetic',
            logicalSessionTimeoutMinutes: 30,
            maxWireVersion: 25
        }),
        collection: (name: string) => ({
            listIndexes: () => ({
                toArray: async () => databaseIndexes
                    .filter((index) => index.collection === name)
                    .map((index) => ({ key: index.keys, ...structuredClone(index.options ?? {}) }))
            }),
            find: () => cursor(name),
            aggregate: () => cursor(name)
        })
    } as unknown as Db;
};

/**
 * Pins the connection settings and Credit reads (on by default) so an inherited rollback flag
 * cannot hide Credits, connects the services to the synthetic database through mocked
 * MongoClient methods, and always releases the cached connection.
 */
const withSyntheticCatalog = async (t: TestContext, run: () => Promise<void>) => {
    const values: Record<string, string> = {
        DB_CONN_STRING: 'mongodb://127.0.0.1:1',
        DB_NAME: 'synthetic',
        CATALOG_CREDIT_READS_ENABLED: 'true'
    };
    const previous = Object.fromEntries(Object.keys(values).map((key) => [key, process.env[key]]));
    Object.assign(process.env, values);
    t.after(() => {
        for (const [key, value] of Object.entries(previous)) {
            if (value === undefined) delete process.env[key];
            else process.env[key] = value;
        }
    });
    const db = syntheticCatalogDatabase();
    t.mock.method(MongoClient.prototype, 'connect', async function (this: MongoClient) { return this; });
    t.mock.method(MongoClient.prototype, 'db', () => db);
    t.mock.method(MongoClient.prototype, 'close', async () => undefined);
    await connectToDatabase({ initializeIndexes: false, logReady: false });
    try {
        await run();
    } finally {
        await disconnectFromDatabase();
        seededRows = {};
    }
};

/**
 * Runs every server builder that composes a displayByline for one Album and one MediaTrack.
 * Public catalog and Library bylines are not client-validated; they are held to the same rules
 * so every builder stays equivalent. Each projection keeps its DTO (none for the Library map)
 * so tests can check key presence and replay Listener summaries through the native ports.
 */
const replayBylineBuilders = async (scenario: ReplayCatalog) => {
    const attributionStatus = scenario.attributionStatus ?? 'documented';
    const credits = scenario.credits.map(([subject, role, joinPhrase], index) => ({
        creditId: `credit_${String(index + 1).padStart(3, '0')}`,
        subjectType: subject.subjectType,
        subjectId: subject.subjectId,
        role,
        ...(joinPhrase === undefined ? {} : { joinPhrase })
    }));
    const hidden = new Set((scenario.hiddenSubjects ?? []).map((subject) => subject.subjectId));
    const trackArtists = scenario.trackArtists ?? [];
    const subjects = [...new Map([...scenario.credits.map(([subject]) => subject), ...trackArtists]
        .filter((subject) => !hidden.has(subject.subjectId))
        .map((subject) => [subject.subjectId, subject])).values()];
    const album = {
        _id: new ObjectId(albumId), title: 'Synthetic Album', lifecycleStatus: 'ready', audioTrackIds: [],
        attributionStatus, credits
    };
    const mediaTrack = {
        _id: new ObjectId(mediaTrackId), title: 'Synthetic MediaTrack', uploadStatus: 'ready',
        s3Key: mediaTrackId, artistIds: trackArtists.map((subject) => subject.subjectId), attributionStatus, credits
    };
    seededRows = {
        albums: [album],
        audioTracks: [mediaTrack],
        artists: subjects.filter((subject) => subject.subjectType === 'artist')
            .map(({ subjectId, name }) => ({ _id: new ObjectId(subjectId), name })),
        organizations: subjects.filter((subject) => subject.subjectType === 'organization')
            .map(({ subjectId, name }) => ({ _id: new ObjectId(subjectId), name, organizationType: 'label' }))
    };
    const listenerAlbum = (await getListenerAlbum(albumId))?.album;
    const listenerTrack = (await getListenerAudioTrack(mediaTrackId))?.audioTrack;
    const [publicAlbum] = await projectPublicAlbums([album]);
    const [publicTrack] = await projectPublicAudioTracks([mediaTrack]);
    const libraryBylines = await resolvePublicCatalogBylines([album]);
    const names = (projection?: { credits?: Array<{ name: string }> }) =>
        (projection?.credits ?? []).map((credit) => credit.name);
    return [
        { surface: 'Listener Album', byline: listenerAlbum?.displayByline, creditNames: names(listenerAlbum), dto: listenerAlbum },
        { surface: 'Listener MediaTrack', byline: listenerTrack?.displayByline, creditNames: names(listenerTrack), dto: listenerTrack },
        { surface: 'public Album', byline: publicAlbum?.displayByline, creditNames: names(publicAlbum), dto: publicAlbum },
        { surface: 'public MediaTrack', byline: publicTrack?.displayByline, creditNames: names(publicTrack), dto: publicTrack },
        { surface: 'Library byline', byline: libraryBylines.get(albumId), creditNames: [] as string[], dto: undefined }
    ];
};

test('every current server byline builder yields the same byline, accepted by both native clients', async (t) => {
    await withSyntheticCatalog(t, async () => {
        for (const scenario of representativeScenarios) {
            for (const projection of await replayBylineBuilders(scenario)) {
                const label = `${scenario.title}: ${projection.surface}`;
                assert.equal(projection.byline, scenario.byline, label);
                for (const name of projection.creditNames) {
                    assert.deepEqual(nativeDisplayTextVerdict(name, nativeCreditNameLimit), accepted, label);
                }
            }
            if (scenario.codePoints !== undefined) {
                assert.equal(Array.from(scenario.byline).length, scenario.codePoints, scenario.title);
            }
            assert.deepEqual(bylineVerdict(scenario.byline), accepted, scenario.title);
        }
    });
});

test('join-phrase bylines are identical on every builder and accepted by both native clients', async (t) => {
    await withSyntheticCatalog(t, async () => {
        for (const scenario of joinPhraseScenarios) {
            for (const projection of await replayBylineBuilders(scenario)) {
                const label = `${scenario.title}: ${projection.surface}`;
                assert.equal(projection.byline, scenario.byline, label);
                for (const name of projection.creditNames) {
                    assert.deepEqual(nativeDisplayTextVerdict(name, nativeCreditNameLimit), accepted, label);
                }
            }
            assert.deepEqual(bylineVerdict(scenario.byline), accepted, scenario.title);
        }
    });
});

test('an empty byline is omitted, so both native clients decode the summary and fall back to artistNames', async (t) => {
    await withSyntheticCatalog(t, async () => {
        for (const scenario of emptyBylineScenarios) {
            const projections = await replayBylineBuilders(scenario);
            for (const projection of projections) {
                const label = `${scenario.title}: ${projection.surface}`;
                assert.equal(projection.byline, undefined, label);
                if (projection.surface === 'Library byline') continue;
                // Every DTO-backed builder must project the owner, or the key checks prove nothing.
                assert.ok(projection.dto, label);
                const omitted = scenario.noAttribution
                    ? ['displayByline', 'credits', 'attributionStatus']
                    : ['displayByline'];
                for (const key of omitted) {
                    assert.equal(Object.prototype.hasOwnProperty.call(projection.dto, key), false, `${label}: ${key}`);
                }
            }
            const listenerSummaries = [
                { surface: 'Listener Album', fallback: scenario.albumFallback },
                { surface: 'Listener MediaTrack', fallback: scenario.trackFallback }
            ].map(({ surface, fallback }) => ({
                surface,
                fallback,
                // The summary exactly as a client parses it from the response body.
                wire: JSON.parse(JSON.stringify(projections.find((projection) => projection.surface === surface)?.dto))
            }));
            for (const { surface, fallback, wire } of listenerSummaries) {
                const label = `${scenario.title}: ${surface}`;
                const shown = { decodes: true, byline: fallback };
                assert.deepEqual(nativeAttributionOutcome(wire), { ios: shown, android: shown }, label);
                // Only an owner with usable attribution ever composed ''; unusable attribution sent no byline.
                if (scenario.noAttribution) continue;
                // The previous payload: '' failed an iOS collection page and an Android page or Album details.
                const failed = { decodes: false, byline: null };
                assert.deepEqual(nativeAttributionOutcome({ ...wire, displayByline: '' }),
                    { ios: failed, android: failed }, label);
            }
        }
    });
});

test('known gaps: current bylines that a native client rejects', async (t) => {
    await withSyntheticCatalog(t, async () => {
        // Administrator catalog text strips only C0 and C1 controls, so the ZWJ (Cf) in an emoji
        // sequence reaches the byline and the Credit name; iOS rejects both, Android accepts them.
        // A stage that strips or rejects Cf in Credit names must update this case.
        const formatCharacter: BylineScenario = {
            title: 'an emoji ZWJ sequence in a primary name',
            credits: [[zwjName, 'primary'], [trio, 'featured']],
            byline: 'Pixel \u{1F469}\u200D\u{1F4BB} Collective, Ipsum Trio'
        };
        for (const projection of await replayBylineBuilders(formatCharacter)) {
            assert.equal(projection.byline, formatCharacter.byline, projection.surface);
        }
        assert.deepEqual(bylineVerdict(formatCharacter.byline), onlyAndroidAccepts);
        assert.deepEqual(nativeDisplayTextVerdict(zwjName.name, nativeCreditNameLimit), onlyAndroidAccepts);
    });
});
